import os

def delete_files_and_folders(directory):
    for root, dirs, files in os.walk(directory, topdown=False):
        for name in files:
            file_path = os.path.join(root, name)
            try:
                os.remove(file_path)
            except OSError as e:
                print(f"Error deleting {file_path}: {e.strerror}")
        for name in dirs:
            dir_path = os.path.join(root, name)
            try:
                os.rmdir(dir_path)
            except OSError as e:
                print(f"Error removing {dir_path}: {e.strerror}")

delete_files_and_folders("C:\\path\\to\\directory")
